<?php require __DIR__.'/config/bootstrap.php'; $title='Latest Posts · '.setting('site_name','PlayGramBlog'); require __DIR__.'/includes/header.php'; $page=max(1,(int)($_GET['page']??1));$per=9;$total=(int)db()->query("SELECT COUNT(*) FROM posts WHERE status='published' AND published_at<=NOW()")->fetchColumn();$st=db()->prepare("SELECT p.*,c.name category,u.name author FROM posts p LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN users u ON u.id=p.author_id WHERE p.status='published' AND p.published_at<=NOW() ORDER BY p.published_at DESC LIMIT $per OFFSET ".(($page-1)*$per));$st->execute();$rows=$st->fetchAll();?><h1>Latest Posts</h1><div class="grid"><?php foreach($rows as $p): ?><article class="card"><div class="pad"><div class="meta"><?=e($p['category'])?> · <?=date('M j, Y',strtotime($p['published_at']))?></div><h2><a href="post.php?slug=<?=e($p['slug'])?>"><?=e($p['title'])?></a></h2><p><?=e(excerpt($p['content']))?></p></div></article><?php endforeach; ?></div><?=pagination($page,$per,$total,'posts.php?page=')?><?php require __DIR__.'/includes/footer.php'; ?>